#!/usr/bin/env python3
"""pygrep.py - a small grep clone.

usage: pygrep.py [options] PATTERN [FILE]*

options:
  -i  case-insensitive matching
  -v  select non-matching lines
  -n  prefix each output line with its 1-based line number
  -c  print only a count of matching lines per file
  -l  print only the names of files with at least one match
  -E  interpret PATTERN as an extended regular expression
      (default: PATTERN is a fixed string, matched as substring)

Reads stdin when no FILE operands are given.

Exit status: 0 if any line was selected, 1 if none, 2 on usage errors
or unreadable input files.
"""

import argparse
import re
import sys


def build_parser():
    p = argparse.ArgumentParser(
        prog="pygrep.py",
        description="A minimal grep clone.",
        usage="pygrep.py [options] PATTERN [FILE]*",
    )
    p.add_argument("-i", dest="ignore_case", action="store_true",
                   help="case-insensitive matching")
    p.add_argument("-v", dest="invert", action="store_true",
                   help="select non-matching lines")
    p.add_argument("-n", dest="line_numbers", action="store_true",
                   help="print line numbers")
    p.add_argument("-c", dest="count", action="store_true",
                   help="print only a count of matching lines")
    p.add_argument("-l", dest="list_files", action="store_true",
                   help="print only names of files with matches")
    p.add_argument("-E", dest="extended", action="store_true",
                   help="PATTERN is an extended regular expression")
    p.add_argument("pattern")
    p.add_argument("files", nargs="*")
    return p


def make_matcher(pattern, ignore_case=False, extended=False):
    """Return predicate(line_text) -> bool."""
    flags = re.IGNORECASE if ignore_case else 0
    if extended:
        rx = re.compile(pattern, flags)

        def match(line):
            return rx.search(line) is not None
    else:
        if ignore_case:
            needle = pattern.casefold()

            def match(line):
                return needle in line.casefold()
        else:
            def match(line):
                return pattern in line
    return match


def main(argv=None):
    args = build_parser().parse_args(argv)
    try:
        matcher = make_matcher(args.pattern, args.ignore_case, args.extended)
    except re.error as exc:
        print(f"pygrep.py: invalid regex: {exc}", file=sys.stderr)
        return 2

    streams = []
    had_error = False

    if args.files:
        for name in args.files:
            try:
                streams.append((name, open(name, "r")))
            except OSError as exc:
                print(f"pygrep.py: {name}: {exc.strerror}", file=sys.stderr)
                had_error = True
    else:
        streams.append((None, sys.stdin))

    any_selected = False

    try:
        for name, stream in streams:
            selected_count = 0
            listed = False
            try:
                for lineno, line in enumerate(stream, start=1):
                    line = line.rstrip("\n")
                    if bool(matcher(line)) != args.invert:
                        any_selected = True
                        selected_count += 1
                        if args.list_files:
                            if name is not None:
                                print(name)
                                listed = True
                            else:
                                print(line)
                            break  # -l: one hit per file is enough
                        prefix = ""
                        if name is not None:
                            prefix += f"{name}:"
                        if args.line_numbers:
                            prefix += f"{lineno}:"
                        if args.count:
                            continue
                        print(f"{prefix}{line}")
            except OSError as exc:
                print(f"pygrep.py: {name}: {exc.strerror}", file=sys.stderr)
                had_error = True
            finally:
                if name is not None:
                    stream.close()
            if args.count and not args.list_files:
                prefix = f"{name}:" if name is not None else ""
                print(f"{prefix}{selected_count}")
            # -l on stdin behaves like normal output (handled above).
    except BrokenPipeError:
        pass

    if had_error:
        return 2
    return 0 if any_selected else 1


if __name__ == "__main__":
    sys.exit(main())

