"""Tests for pygrep.py covering exit codes and output formats."""

import subprocess
import sys

import pytest

PYGREP = [sys.executable, "pygrep.py"]


@pytest.fixture
def samples(tmp_path):
    """Two inline sample files used across the suite."""
    alpha = tmp_path / "alpha.txt"
    beta = tmp_path / "beta.txt"
    alpha.write_text("apple pie\nbanana split\ncherry tart\nApple juice\n")
    beta.write_text("banana bread\ngrape jam\nBANANA smoothie\n")
    return {"alpha": str(alpha), "beta": str(beta), "dir": tmp_path}


def run(args, **kw):
    return subprocess.run(
        PYGREP + args, capture_output=True, text=True, **kw
    )


# ---------------------------------------------------------------- exit codes

class TestExitCodes:
    def test_match_exits_zero(self, samples):
        r = run(["apple", samples["alpha"]])
        assert r.returncode == 0

    def test_no_match_exits_one(self, samples):
        r = run(["watermelon", samples["alpha"], samples["beta"]])
        assert r.returncode == 1

    def test_unreadable_file_exits_two(self, samples):
        r = run(["apple", samples["dir"] / "missing.txt"])
        assert r.returncode == 2
        assert r.stderr

    def test_usage_error_missing_pattern_exits_two(self):
        r = run([])
        assert r.returncode == 2

    def test_usage_error_unknown_option_exits_two(self, samples):
        r = run(["-Z", "apple", samples["alpha"]])
        assert r.returncode == 2

    def test_stdin_no_match_exits_one(self):
        r = run(["zzz"], input="hello\nworld\n")
        assert r.returncode == 1


# ------------------------------------------------------------ output formats

class TestPlainOutput:
    def test_single_file_bare_lines(self, samples):
        r = run(["apple", samples["alpha"]])
        assert r.stdout.splitlines() == ["apple pie", "Apple juice"]

    def test_multiple_files_prefixed_with_filename(self, samples):
        r = run(["banana", samples["alpha"], samples["beta"]])
        assert r.stdout.splitlines() == [
            f"{samples['alpha']}:banana split",
            f"{samples['beta']}:banana bread",
            f"{samples['beta']}:BANANA smoothie",
        ]

    def test_fixed_string_not_regex(self, samples):
        r = run(["a.ple", samples["alpha"]])
        assert r.stdout == ""
        assert r.returncode == 1


class TestLineNumberOutput:
    def test_n_single_file(self, samples):
        r = run(["-n", "tart", samples["alpha"]])
        assert r.stdout.splitlines() == ["3:cherry tart"]
        assert r.returncode == 0

    def test_n_multiple_files(self, samples):
        r = run(["-n", "jam", samples["alpha"], samples["beta"]])
        assert r.stdout.splitlines() == [f"{samples['beta']}:2:grape jam"]

    def test_n_counts_all_lines(self, samples):
        r = run(["-n", "smoothie", samples["beta"]])
        assert r.stdout.splitlines() == ["3:BANANA smoothie"]


class TestCountOutput:
    def test_c_single_file(self, samples):
        r = run(["-c", "apple", samples["alpha"]])
        assert r.stdout == "2\n"
        assert r.returncode == 0

    def test_c_multiple_files(self, samples):
        r = run(["-c", "banana", samples["alpha"], samples["beta"]])
        assert r.stdout == f"{samples['alpha']}:1\n{samples['beta']}:2\n"

    def test_c_zero_still_reported(self, samples):
        r = run(["-c", "kiwi", samples["alpha"]])
        assert r.stdout == "0\n"
        assert r.returncode == 1


class TestListFilesOutput:
    def test_l_lists_matching_file_only(self, samples):
        r = run(["-l", "grape", samples["alpha"], samples["beta"]])
        assert r.stdout == f"{samples['beta']}\n"
        assert r.returncode == 0

    def test_l_no_match_prints_nothing(self, samples):
        r = run(["-l", "papaya", samples["alpha"], samples["beta"]])
        assert r.stdout == ""
        assert r.returncode == 1


# ------------------------------------------------------------- flag behavior

class TestFlags:
    def test_i_ignore_case(self, samples):
        r = run(["-i", "APPLE", samples["alpha"]])
        assert r.stdout.splitlines() == ["apple pie", "Apple juice"]

    def test_v_invert(self, samples):
        r = run(["-v", "banana", samples["beta"]])
        assert r.stdout.splitlines() == ["grape jam"]

